dataset <- tryCatch({
  read.csv("metrics.csv", stringsAsFactors = FALSE)
}, error = function(err) {
  warning("Could not load metrics: ", err$message)
  data.frame()
})

normalized_matrix <- apply(numeric_matrix, MARGIN = 2, function(x) {
  (x - mean(x)) / sd(x)
})

new_report <- function(title, pages = 1) {
  structure(list(title = title, pages = pages), class = "report")
}
print.report <- function(x, ...) {
  cat(sprintf("Report: '%s' (%d pages)\n", x$title, x$pages))
}

res <- parallel::mclapply(1:4, function(i) {
  Sys.sleep(0.1)
  i^2
}, mc.cores = 2)

tidy_summary <- function(df, num_col) {
  stopifnot(is.data.frame(df))
  col_data <- df[[num_col]]
  list(
    mean = mean(col_data, na.rm = TRUE),
    median = median(col_data, na.rm = TRUE),
    iqr = IQR(col_data, na.rm = TRUE)
  )
}
